---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

-- Toggle between US and French AZERTY layouts.
hl.bind(mainMod .. " + SHIFT + SPACE", hl.dsp.exec_cmd("hyprctl switchxkblayout all next"))

-- Core Apps & Menu
hl.bind("SUPER + CTRL + T", hl.dsp.exec_cmd("@HOME@/.local/bin/theme-selector.sh"))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("exit"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-keybindings"))
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("@HOME@/.local/bin/everforest-wallpaper --pick"))
-- Super+P toggles a comfortably sized, centered floating window. Keep the
-- dwindle pseudo-tile toggle on Super+Shift+P.
hl.bind(mainMod .. " + P", function ()
    local window = hl.get_active_window()
    if not window then return end

    if window.floating then
        hl.dispatch(hl.dsp.window.float({ action = "unset", window = window }))
    else
        hl.dispatch(hl.dsp.window.float({ action = "set", window = window }))
        hl.dispatch(hl.dsp.window.resize({ x = 1440, y = 864, window = window }))
        hl.dispatch(hl.dsp.window.center({ window = window }))
    end
end)
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-center-layout"))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("hyprlock"))

-- Screenshots save to Pictures/Screenshots, copy to clipboard, and show a confirmation.
hl.bind("Print", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot full"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("@HOME@/.local/bin/hypr-screenshot area"))

-- Focus Windows
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move Windows
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))

-- Workspaces
for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Special Scratchpad
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Mouse Binds
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Hardware / Laptop Media Keys
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -n2 set 5%-"),                  { locked = true, repeating = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Give VS Code a barely translucent surface so Hyprland can blur behind it.
-- This uses the compositor only; no VS Code extension or injected CSS is needed.
hl.window_rule({
    name = "code-subtle-blur",
    match = { class = "com.microsoft.VSCode" },
    opacity = "0.98 0.98",
})

-- Treat application dialogs and authentication popups as centered overlays.
hl.window_rule({
    name  = "center-modal-dialogs",
    match = { modal = true },
    float = true,
    center = true,
})

-- Keep browser authentication popups in the browser's tiled window layout.
-- The generic modal rule above would otherwise make Helium's OAuth window
-- float over the page that opened it.
hl.window_rule({
    name  = "tile-helium-auth-popups",
    match = { class = "helium", modal = true },
    float = false,
})

-- Theme colors and window appearance are selected by switch-theme.sh.
dofile("@HOME@/.config/hypr/theme-active.lua")

